MIRRORS = ("aggregates.csv", "aggregates.tsv", "aggregates.xml", "aggregates.ini",
           "aggregates.env", "aggregates.md", "aggregates.txt")
PROBE_CORPUS = "c03_port_exposure"


def _scratch_data() -> Path:
    # A private copy of the shipped inputs in which one corpus keeps only every other line,
    # so the agent's CLI must reduce what it is given rather than echo a delivered file.
    data = Path(tempfile.mkdtemp(prefix="sealb-data-"))
    os.chmod(data, 0o755)
    for src in shipped_dir().iterdir():
        body = src.read_bytes()
        if src.name.startswith(PROBE_CORPUS + "."):
            body = b"".join(body.splitlines(keepends=True)[::2])
        (data / src.name).write_bytes(body)
        os.chmod(data / src.name, 0o644)
    return data


def _cli_reproduces():
    data = shipped_dir()
    work = Path(tempfile.mkdtemp(prefix="sealb-compile-"))
    os.chmod(work, 0o777)
    for name in ("config.json", "tool.zip"):
        shutil.copyfile(OUT / name, work / name)
        os.chmod(work / name, 0o666)
    result = run_tool("compile", "--data", str(data), "--out", str(work))
    assert result.returncode == 0
    for name in ("aggregates.json", "zone_totals.json", "corpus_index.json", *MIRRORS):
        assert (work / name).read_bytes() == (OUT / name).read_bytes()
    delivered = load("aggregates.json")
    for spec in defs():
        r = run_tool("aggregate", "--corpus", spec["name"], "--data", str(data), "--out", str(work))
        assert r.returncode == 0 and r.stdout == f"{delivered[spec['name']]}\n"
    r = run_tool("plan", "--data", str(data), "--out", str(work), "--env", "base")
    assert r.returncode == 0 and r.stdout == (OUT / "config.json").read_text(encoding="utf-8")
    for zone in ZONE_LIST:
        r = run_tool("plan", "--data", str(data), "--out", str(work), "--env", zone)
        assert r.returncode == 0 and r.stdout == (OUT / f"profile_{zone}.json").read_text(encoding="utf-8")
    probe = next(spec for spec in defs() if spec["name"] == PROBE_CORPUS)
    full = triples(probe["fmt"], raw(f"{probe['name']}.{probe['ext']}"))
    shifts = [s for s in range(179)
              if reduce_corpus(probe["op"], full, probe["lo"], probe["hi"] + s) == delivered[probe["name"]]]
    altered = _scratch_data()
    rows = triples(probe["fmt"], (altered / f"{probe['name']}.{probe['ext']}").read_text(encoding="utf-8"))
    expected = {f"{reduce_corpus(probe['op'], rows, probe['lo'], probe['hi'] + s)}\n" for s in shifts}
    r = run_tool("aggregate", "--corpus", probe["name"], "--data", str(altered), "--out", str(work))
    assert r.returncode == 0
    if expected:
        assert r.stdout in expected
    else:
        assert r.stdout.strip().lstrip("-").isdigit() and r.stdout != f"{delivered[probe['name']]}\n"


